	"before_deactivation_to_know_detail_five": "‏إذا كنتِ ترغبين في تنزيل {{}}بيانات X الخاصة بكِ{{}}، فسيتعين عليكِ إكمال كلٍّ من الطلب وعملية التنزيل قبل تعطيل حسابكِ. لا يمكن إرسال روابط تنزيل بياناتكِ إلى الحسابات المعطلة.",
