	"first_moderated_reply_education_description": "\"‏لمنحكِ المزيد من التحكم في المحادثات التي تبدئينها، يمكن لمؤلفي المنشورات إخفاء الردود على منشوراتهم.\n\nيتم نقل الردود المخفية إلى صفحة منفصلة، ويمكن لأي شخص عرضها بتحديد أيقونة الرد المخفي على المنشور. {{}}معرفة المزيد{{}}\"",
