	"gift_premium_terms_footer": "‏يتم احتساب سعر الاشتراك الهدية عند الشراء وهو غير قابل للاسترداد. إنه استخدام لمرة واحدة، وهو غير قابل للاستبدال، وغير قابل للدمج، وليس له قيمة نقدية. يبدأ الاشتراك بعد قيام منصة X بالمراجعة والتعيين للمستلمة، التي يجب أن تقر بـ %1$sوالسياسات المتبعة لدينا. إذا فشلت المستلِمة في تلبية أي متطلبات للأهلية أو ألغت الاشتراك أو رفضت شروطنا وسياساتنا، فإن الهدية تكون غير قابلة للحصول عليها وغير قابلة للاسترداد. قد يتم تطبيق الضرائب. قد تتغير الشروط. %2$s",
