	"golive__tip_broadcaster_1": "‏<b>نصيحة:</b> نشكركِ على بدء بثٍ مباشر! يمكنكِ الترحيب بالأشخاص عند انضمامهم إلى الفيديو الخاص بكِ بقول \\\"مرحبًا\\\".",
	"golive__tip_broadcaster_10": "‏<b>تلميح:</b> شكرًا لكِ على البث المباشر على X! <3",
	"golive__tip_broadcaster_2": "‏<b>نصيحة:</b> جرّبي ذكر الأشخاص بأسمائهم عند انضمامهم إلى فيديو البث المباشر، سيشعرهم ذلك بسعادة غامرة!",
	"golive__tip_broadcaster_3": "‏<b>نصيحة:</b> احرصي على استخدام البث المباشر لعدة دقائق على الأقل لكي يعثر الأشخاص عليكِ بسهولة أكثر.",
	"golive__tip_broadcaster_4": "‏<b>نصيحة:</b> اسألي المشاهدين عن موطنهم، فهذه طريقة رائعة لكسر الحواجز بينكِ وبينهم.",
	"golive__tip_broadcaster_5": "‏<b>نصيحة:</b> احرصي على تقديم الشكر للأشخاص على مشاركتهم واحرصي كذلك على الرد على تعليقاتهم لكي يستمروا في المتابِعة.",
	"golive__tip_broadcaster_6": "‏<b>نصيحة:</b> إذا فقدتِ الاتصال أثناء البث المباشر، فانتقلي إلى مكان به إشارة أفضل.",
	"golive__tip_broadcaster_7": "‏<b>نصيحة:</b> اطلبي من الأشخاص أن يتابعوكِ حتى تصلهم تنبيهات في المرة القادمة التي تبدئين فيها بثًا مباشرًا.",
	"golive__tip_broadcaster_8": "‏<b>نصيحة:</b> ابدئي فيديو البث المباشر بإلقاء التحية مباشرةً بقول \\\"مرحبًا\\\". سيعجب بذلك الأشخاص الذين سيشاهدونه فيما بعد.",
	"golive__tip_broadcaster_9": "‏<b>نصيحة:</b> احرصي على تقديم الشكر للأشخاص على مشاهدتهم قبل أن تنهي فيديو البث المباشر.",
	"golive__tip_pre_broadcast_1": "‏<b>نصيحة:</b> اكتبي عنوانًا قبل بدأ البث المباشر لمساعدة الأشخاص على اكتشاف الفيديو الخاص بكِ.",
	"golive__tip_pre_broadcast_2": "‏<b>نصيحة:</b> يساعد العنوان الوصفي الأشخاص في فهم موضوع فيديو البث المباشر بشكل أفضل.",
	"golive__tip_pre_broadcast_3": "‏<b>نصيحة:</b> هل تبحثين عن أفكار؟ يمكنكِ إلقاء نظرة، أو مشاركة موهبة، أو التحدث حول شيء يثير اهتمامكِ.",
	"golive__tip_pre_broadcast_4": "‏<b>نصيحة:</b> تأكدي من وجود إشارة هاتف قوية قبل بدأ البث المباشر.",
	"golive__tip_pre_broadcast_5": "‏<b>نصيحة:</b> يمكنكِ إضافة هاشتاج إلى العنوان لمساعدة الأشخاص في اكتشاف فيديو البث المباشر الخاص بكِ.",
	"golive__tip_pre_broadcast_6": "‏<b>تلميح:</b> هذه هي كل التلميحات التي لدينا حاليًا، شكرًا لكِ على البث المباشر على X!",
	"google_disclaimer": "‏تتم مشاركة معلومات العنوان مع Google. راجعي {{}}شروط خدمة خرائط Google{{}} و{{}}سياسة خصوصية Google{{}} لمعرفة المزيد.",
