	"identity_education_cancel": "‏تخطٍ الآن",
	"identity_education_conditions": "‏أوافق على استخدام X وAu10tix لصور بطاقة هويتي وصوري الشخصية، بما في ذلك بيانات القياسات الحيوية التي تم استخراجها، لتأكيد هويتي وللأغراض المتعلقة بالسلامة والأمان لدى X، بما في ذلك منع انتحال الشخصية. ويجوز لـ Au10tix تخزين هذه البيانات لمدة تصل إلى 30 يومًا. {{}}معرفة المزيد{{}}",
	"identity_education_conditions_age_verification": "‏أوافق على استخدام X وPersona لصور هويتي وصورتي لتأكيد عمري. لن يتم تخزين صورتكِ. قد تحتفظ X وxAI بمعلومات عن عمركِ. {{}}معرفة المزيد{{}}",
	"identity_education_conditions_eea": "\"‏أوافق على مشاركة X لصور بطاقة هويتي؛ بما في ذلك بيانات القياسات الحيوية، وبيانات شخصية من ملفي الشخصيّ مع Au10tix بغرض التحقق من هويتي.\nأوافق أيضًا على تخزين X لصور بطاقة هويتي؛ بما في ذلك بيانات القياسات الحيوية، لمدة تصل إلى 30 يومًا واستخدامه لها، وكذلك بيانات من ملفي الشخصيّ لأغراض السلامة والأمن؛ بما في ذلك منع انتحال الشخصيّة. {{}}معرفة المزيد{{}}\"",
	"identity_education_conditions_persona_vendor": "‏أوافق على استخدام X وPersona لصور بطاقة هويتي وصورتي الشخصية، بما في ذلك بيانات القياسات الحيوية المستخرجة، لتأكيد هويتي، ولأغراض السلامة والأمان ذات الصلة بـ X، ومنع الاحتيال، والدفع. قد تقوم Persona بتخزين هذه البيانات لمدة تصل إلى 30 يومًا. قد تقوم منصة X بتخزين الاسم الكامل، والعنوان، وتجزئات رقم مستند بطاقة هويتي ما دمت أشترك في خدمة X Premium. {{}}معرفة المزيد{{}}",
