	"payment_funds_insurance_footer_secondary_text": "‏يمكنكِ الاطلاع على مزيد من المعلومات بشأن تأمين المؤسسة الفيدرالية لتأمين الودائع (FDIC) وفئات ملكية الحسابات ﻿هنا﻿.",
	"payment_funds_insurance_footer_text": "‏تُحفظ ودائعكِ لدى بنك Cross River Bank، العضو في المؤسسة الفيدرالية لتأمين الودائع (FDIC)، وهي مؤمَّنة من قِبل المؤسسة الفيدرالية لتأمين الودائع (FDIC) حتى مبلغ 250,000 دولار أمريكي لكل فرد ولكل كيان قانوني لجميع الحسابات في كل فئة من فئات ملكية الحسابات الموجودة في البنك (مجتمعة)، بما في ذلك الحسابات المحتفَظ بها بصفة تمثيلية.",
	"payment_funds_insurance_footer_text_format": "‏يتم الاحتفاظ بودائعك لدى بنك Cross River Bank (يُشار إليه باسم \\\"البنك\\\")، وهو عضو في مؤسسة تأمين الودائع الفيدرالية (FDIC)، ومؤمّن عليها من قبل مؤسسة تأمين الودائع الفيدرالية (FDIC) حتى {amount} لكل فرد ولكل كيان قانوني لجميع الحسابات في كل فئة ملكية حساب المحتفظ بها في البنك (مجتمعة)، بما في ذلك الحسابات المحتفظ بها بصفة تمثيلية.",
	"payment_funds_insurance_sweep_disclaimer": "‏تُحفظ الودائع لدى بنك كروس ريفر، العضو في مؤسسة تأمين الودائع الفيدرالية (FDIC)، ولدى مؤسسات أخرى مؤمّنة من قِبل مؤسسة تأمين الودائع الفيدرالية. يجب استيفاء شروط معينة لتطبيق تغطية تأمين الودائع. شركة X Payments LLC ليست بنكًا مؤمّنًا من قِبل مؤسسة تأمين الودائع الفيدرالية. يغطي تأمين الودائع فقط إفلاس البنك المؤمّن.",
	"payment_funds_insurance_sweep_presentation": "‏يتم تسجيل ودائعك تلقائيًا في برنامج X Cash Sweep، الذي يوفر تغطية تأمينية إجمالية من المؤسسة الفيدرالية لتأمين الودائع (FDIC) تصل إلى 10 ملايين دولار، مع مراعاة بعض القيود. ﻿معرفة المزيد﻿.",
