	"payment_international_wire_disclaimer_dispute_with_url_format": "‏يحق لكِ الاعتراض على أي خطأ في معاملتكِ. إذا كنتِ تعتقدين بوجود خطأ، يُرجى التواصل مع شركة X Payments LLC خلال {days} يوم عبر الاتصال على الرقم {phone}، أو عبر البريد على العنوان {address}، أو بزيارة الموقع الإلكتروني {url}. كما يمكنكِ التواصل معنا للحصول على شرح كتابي لحقوقكِ.",
	"payment_international_wire_disclaimer_fees": "‏تشمل هذه الرسوم الرسوم التي تفرضها شركة X Payments وبنك Cross River Bank عند الاقتضاء.",
	"payment_international_wire_disclaimer_only_individuals": "‏تتوفر التحويلات الدولية حاليًا للأفراد فقط.",
	"payment_international_wire_disclaimer_processing_time": "‏قد يتم تفعيل التحويل في وقت أقرب، أو قد يتأخر أو يتوقف في حالة اكتشاف أي مشكلة.",
