	"room_settings_clips_description": "\"‏عند إنشاء كليب، سيتم التقاط آخر 30 ثانية من الصوت. \n \nبصفتكِ مضيفة، يمكنكِ حذف الكليبات التي أنشأها أشخاصٌ آخرون من مساحتكِ. ولكن إذا حذفتِ كليبًا واحدًا من مساحتكِ، فسيتم حذف جميع الكليبات من المساحة نفسها. \n \nإذا سجلتِ مساحة ثم حذفتِها، فسيتم أيضًا حذف أي كليب من تلك المساحة. \n \nتنتهي صلاحية جميع الكليبات بعد 30 يومًا.\"",
