	"room_settings_delete_recording_prompt_desc": "\"‏إذا حذفتِ تسجيلكِ، فلن يتمكن أي شخص من الاستماع إلى مساحتكِ بعد انتهائها.\n سيحتفظ X بنسخة من هذه المساحة لمدة 30 يومًا على الأقل لمراجعتها بحثًا عن محاولات الإزعاج وإساءة الاستخدام.\"",
