	"safety_mode_settings_error": "‏لا يمكن تحديث إعدادات وضع الأمان.",
	"safety_mode_settings_half_sheet_description_1": "‏عندما نكتشف ردودًا أو إشارات أو اقتباسات قد تكون مسيئة أو غير مرغوب فيها، فإننا نحظر الحسابات القائمة بها تلقائيًا لفترة مؤقتة. وعلى عكس الحظر اليدوي، يستمر الحظر التلقائي لمدة أسبوع فقط.",
	"safety_mode_settings_half_sheet_description_2": "‏الحسابات المحظورة تلقائيًا، تمامًا مثل الحسابات المحظورة يدويًا، لا يمكنها رؤية منشوراتكِ، أو متابعتكِ، أو إرسال رسائل إليكِ. وإذا حاول مستخدمو هذه الحسابات عرض ملفكِ الشخصي، فسنخبرهم بأن X هو مَن حظرهم تلقائيًا، وليس أنتِ.",
