	"tipjar_confirmation_next_text": "‏التالي",
	"tipjar_confirmation_rationale_profile": "‏قدّمي إكراميات بالقدر الذي تريدينه. لا يتم إرسال أي أموال إلى X. عند تقديم الإكراميات، ستكونين خاضعة لشروط المنصة التابعة لجهة خارجية. وهذا يعني أنه قد تتم مشاركة اسمكِ ورقم هاتفكِ وبريدكِ الإلكتروني ومعلوماتكِ الشخصية الأخرى مع متلقي الإكرامية.",
