	"tipjar_input_invalid_url": "‏عنوان URL غير صالح",
	"tipjar_input_rationale": "‏سيرسل الأشخاص مدفوعات إلى اسم المستخدم الذي أدخلتِه أعلاه. من خلال إضافة اسم المستخدم الخاص بكِ وقبول الإكراميات، قد تكشفين عن معلومات عن نفسك تمت مشاركتها في خدمة الدفع، بما في ذلك اسمكِ، وعنوان بريدكِ الإلكترونيّ، ومعلومات أخرى.",
	"tipjar_input_rationale_bitcoin": "‏سيرسل الأشخاص المدفوعات إلى عنوان Bitcoin الذي أدخلتِه أعلاه.",
	"tipjar_input_rationale_kakao_pay": "\"‏سيرسل الأشخاص الإكراميات إلى رابط QR الذي أدخلتِهِ أعلاه.\nعند إضافة رابط QR الخاص بكِ وقبول الإكراميات، قد تكشفين عن معلومات تخصكِ تمت مشاركتها في خدمة الدفع؛ بما في ذلك اسمكِ، وعنوان بريدكِ الإلكترونيّ، ومعلومات أخرى.\n\nيمكن العثور على رابط QR لـ KakaoPay في KakaoTalk من المزيد > الماسح الضوئي أعلى اليسار > رمز الأموال > أيقونة صورة الحافظة. اضغطي على الأيقونة لنسخ الرابط إلى حافظتكِ، ثم الصقيه أعلاه.\"",
	"tipjar_input_rationale_paytm": "‏سيرسل الأشخاص الإكراميات إلى رقم الهاتف المحمول المرتبط بـ Paytm الذي أدخلتِه أعلاه. عند إضافة رقم هاتفكِ المحمول وقبول الإكراميات، قد تكشفين عن معلومات تخصكِ تمت مشاركتها في خدمة الدفع؛ بما في ذلك اسمكِ، وعنوان بريدكِ الإلكترونيّ، ورقم هاتفكِ المحمول، ومعلومات أخرى.",
